script:
// ---------------- Child Table Script ----------------
frappe.ui.form.on("Consumption Log Item", {
    utility: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);

        if (row.utility) {
            frappe.db.get_value("Utility", row.utility, "rate")
                .then(r => {
                    if (r && r.message) {
                        let rate = r.message.rate || 0;
                        frappe.model.set_value(cdt, cdn, "rate", rate);
                        frappe.model.set_value(cdt, cdn, "amount", (row.units || 0) * rate);
                    }

                    frm.refresh_field("consumption_items");
                    calculate_total(frm); // ✅ directly call helper
                });
        }
    },

    units: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        frappe.model.set_value(cdt, cdn, "amount", (row.units || 0) * (row.rate || 0));
        frm.refresh_field("consumption_items");
        calculate_total(frm); // ✅ directly call helper
    },

    rate: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        frappe.model.set_value(cdt, cdn, "amount", (row.units || 0) * (row.rate || 0));
        frm.refresh_field("consumption_items");
        calculate_total(frm); // ✅ directly call helper
    },

    amount: function(frm, cdt, cdn) {
        calculate_total(frm); // ✅ when manually editing amount
    }
});

// ---------------- Parent DocType Script ----------------
frappe.ui.form.on("Consumption Log", {
    refresh: function(frm) {
        calculate_total(frm); // ✅ recalc total on form load
    },

    // ✅ Optional: Recalculate if child table is changed (row added/removed)
    consumption_items_add: function(frm) {
        calculate_total(frm);
    },
    consumption_items_remove: function(frm) {
        calculate_total(frm);
    }
});

// ---------------- Helper Function ----------------
function calculate_total(frm) {
    let total = 0;

    // Loop through all rows in the child table
    (frm.doc.consumption_items || []).forEach(row => {
        total += flt(row.amount) || 0;
    });

    frm.set_value("total_amount", total);
    frm.refresh_field("total_amount");
}

frappe.ui.form.on("Bill", {
    refresh(frm) {
        calculate_totals(frm);
    },

    resident(frm) {
        // Auto fetch email from Resident record
        if (frm.doc.resident) {
            frappe.db.get_value("Resident", frm.doc.resident, "email")
                .then(r => {
                    if (r && r.message && r.message.email) {
                        frm.set_value("custom_email", r.message.email);
                    }
                });
        }
    },

    due_date(frm) {
        calculate_totals(frm);
    },

    late_fee_per_day(frm) {
        calculate_totals(frm);
    },

    validate(frm) {
        calculate_totals(frm);
    }
});

frappe.ui.form.on("Bill Item", {
    amount(frm, cdt, cdn) {
        calculate_totals(frm);
    },
    items_remove(frm) {
        calculate_totals(frm);
    }
});

function calculate_totals(frm) {
    if (!frm.doc.due_date) return;

    // Get today's date and due date
    const today = frappe.datetime.now_date();
    const due = frm.doc.due_date;

    // Calculate days late
    const days_late = frappe.datetime.get_diff(today, due);
    const valid_days_late = days_late > 0 ? days_late : 0;

    // Late fee calculation
    const late_fee_per_day = frm.doc.late_fee_per_day || 0;
    const late_fee_amount = valid_days_late * late_fee_per_day;

    // Calculate total consumption amount
    let consumption_total = 0;
    (frm.doc.items || []).forEach(row => {
        consumption_total += flt(row.amount || 0);
    });

    // Final total = consumption total + late fee
    const grand_total = consumption_total + late_fee_amount;

    // Set values
    frm.set_value("days_late", valid_days_late);
    frm.set_value("late_fee_amount", late_fee_amount);
    frm.set_value("total_with_late", grand_total);

    frm.refresh_field("days_late");
    frm.refresh_field("late_fee_amount");
    frm.refresh_field("total_with_late");
}
